lab.solution:
def current_map(domain, pairs):
    result = {}
    for learner, lesson in pairs:
        if learner not in domain:
            raise ValueError('unknown learner')
        if learner in result and result[learner] != lesson:
            raise ValueError('conflict')
        result[learner] = lesson
    if set(result) != set(domain):
        raise ValueError('missing learner')
    return result

assert current_map({'Ada', 'Bo'}, [('Ada', 'Loops'), ('Bo', 'Files')]) == {
    'Ada': 'Loops', 'Bo': 'Files'}
for bad in ([('Ada', 'Loops'), ('Ada', 'Files'), ('Bo', 'Files')],
            [('Ada', 'Loops')],
            [('Ada', 'Loops'), ('Bo', 'Files'), ('Cy', 'Input')]):
    try:
        current_map({'Ada', 'Bo'}, bad)
    except ValueError:
        pass
    else:
        raise AssertionError('invalid mapping accepted')
print('mapping contract checked')

